import { existsSync, readFileSync } from 'node:fs';
import { dirname, extname, resolve } from 'node:path';
import { parseSync, Visitor } from 'vite';
const EXTENSIONS = ['', '.ts', '.js', '.mjs', '.cjs'];
/**
 * Resolves a local module if it exists.
 * @param fromFile
 * @param specifier
 */
const resolveLocalModule = (fromFile, specifier) => {
    const base = resolve(dirname(fromFile), specifier);
    const candidates = [
        base,
        base.replace(/\.js$/, '.ts'),
        ...EXTENSIONS.map((ext) => base + ext),
        ...EXTENSIONS.map((ext) => resolve(base, `index${ext}`)),
    ];
    return candidates.find((candidate) => EXTENSIONS.includes(extname(candidate)) && existsSync(candidate) && !candidate.endsWith('/'));
};
/**
 * Asserts that a given source file does not contain any `console` usage.
 * @param src
 */
export const assertConsole = (src) => {
    const seen = new Set();
    const stack = [src];
    while (stack.length > 0) {
        const file = stack.pop();
        if (!file || seen.has(file)) {
            continue;
        }
        seen.add(file);
        const { program, module: esm, errors } = parseSync(file, readFileSync(file, 'utf8'));
        if (errors.length > 0) {
            throw new Error(`Failed to parse ${file}: ${errors.map((e) => e.message).join(', ')}`);
        }
        new Visitor({
            MemberExpression(node) {
                if (node.object.type === 'Identifier' && node.object.name === 'console') {
                    // @todo: improve error message to include doc link.
                    const err = new Error('Console logging is not allowed in Durable functions. ' +
                        `at ${file} ` +
                        'Use the provided durable logger `logger.log()` or `ctx.log()` instead.');
                    err.stack = undefined;
                    throw err;
                }
            },
        }).visit(program);
        const isLocal = (str) => str.startsWith('./') || str.startsWith('../');
        const imports = esm.staticImports.map((item) => item.moduleRequest.value);
        const reExports = esm.staticExports.flatMap((exp) => exp.entries.flatMap((entry) => entry.moduleRequest && !entry.isType ? [entry.moduleRequest.value] : []));
        const specs = [...imports, ...reExports].filter(isLocal);
        for (const spec of specs) {
            const resolved = resolveLocalModule(file, spec);
            if (resolved) {
                stack.push(resolved);
            }
        }
    }
};
